return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'mr','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:23+00:00','po-revision-date'=>'2026-10-31T05:53:23+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'तुमच्या साइटवर आधीपासून इंस्टॉल केलेल्या प्लगइन आणि थीमसाठी गहाळ भाषांतरे भरते.','Translations'=>'भाषांतरे','Babilim Settings'=>'Babilim सेटिंग्ज','Settings'=>'सेटिंग्ज','You are not allowed to do this.'=>'तुम्हाला हे करण्याची परवानगी नाही.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'कमी घटक निवडा: प्रत्येक रनमध्ये जास्तीत जास्त %1$d ऑपरेशन्स (तुम्ही %2$d निवडले).','That component is not installed on this site, so a translation cannot be requested for it.'=>'हा घटक या साइटवर इंस्टॉल केलेला नाही, त्यामुळे त्यासाठी भाषांतराची विनंती करता येत नाही.','Already installed.'=>'आधीपासून इंस्टॉल केलेले आहे.','Downloaded and installed.'=>'डाउनलोड करून इंस्टॉल केले.','Babilim has not been enabled for this site yet.'=>'या साइटसाठी Babilim अद्याप सक्षम केलेले नाही.','No build is available to download for this locale.'=>'या लोकेलसाठी डाउनलोड करण्यासाठी कोणतीही बिल्ड उपलब्ध नाही.','Rolled back to the previous build.'=>'मागील बिल्डवर परत नेले.','Rolled back and reported.'=>'मागे नेले आणि कळवले.','Rolled back, but the report could not be sent: %s'=>'रोलबॅक झाला, परंतु अहवाल पाठवता आला नाही: %s','Removed.'=>'काढले.','Translation requested.'=>'भाषांतराची विनंती केली.','This component was already uploaded. Babilim is checking it now.'=>'हा घटक आधीच अपलोड केला होता. Babilim आता तो तपासत आहे.','Upload cancelled.'=>'अपलोड रद्द केले.','Upload complete — translation requested.'=>'अपलोड पूर्ण झाले — भाषांतराची विनंती केली.','This component does not declare a version number, so a translation cannot be requested for it.'=>'या घटकाने आवृत्ती क्रमांक घोषित केलेला नाही, त्यामुळे त्यासाठी भाषांतराची विनंती करता येत नाही.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'या घटकाचा आवृत्ती क्रमांक %d वर्णांपेक्षा मोठा आहे, जो Babilim हाताळू शकत नाही, त्यामुळे त्यासाठी भाषांतराची विनंती करता येत नाही.','A translation cannot be requested for that locale on this site right now.'=>'या साइटवर सध्या त्या लोकेलसाठी भाषांतराची विनंती करता येत नाही.','Thank you. Your report was sent.'=>'धन्यवाद. तुमचा अहवाल पाठवला गेला.','This report does not name a valid plugin or theme and locale.'=>'हा अहवाल वैध प्लगइन किंवा थीम यांचे नाव आणि लोकेल नमूद करत नाही.','Please choose a category for this report.'=>'कृपया या अहवालासाठी एक श्रेणी निवडा.','This report is missing a valid build to report against.'=>'या अहवालासाठी तक्रार नोंदवण्याकरिता वैध बिल्ड उपलब्ध नाही.','This build is not one this site currently knows about for this component/locale.'=>'ही बिल्ड या घटक/लोकेलसाठी ही साइट सध्या ओळखत असलेली बिल्ड नाही.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" हे फील्ड खूप मोठे आहे: त्यात %2$d अक्षरे आहेत आणि मर्यादा %3$d आहे. काहीही पाठवले गेले नाही; कृपया ते लहान करा आणि पुन्हा प्रयत्न करा.','Original string'=>'मूळ स्ट्रिंग','String context'=>'स्ट्रिंगचा संदर्भ','Current translation'=>'सध्याचे भाषांतर','Suggested translation'=>'सुचवलेले भाषांतर','Note (optional)'=>'टीप (ऐच्छिक)','Where you saw this (optional)'=>'हे तुम्ही कुठे पाहिले (ऐच्छिक)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'सेवेने विनंत्यांच्या वारंवारतेवर मर्यादा घातल्यामुळे Babilim सिंकला तात्पुरता विलंब होत आहे; %s नंतर पुन्हा प्रयत्न केला जाईल.','That is not a valid WordPress locale code. Nothing was saved.'=>'हा वैध WordPress लोकेल कोड नाही. काहीही जतन केले नाही.','Settings saved.'=>'सेटिंग्ज सेव्ह केल्या.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'हे चालू असल्यास, अनइन्स्टॉल केल्यावर या साइटची ओळख देखील पुसली जाते. या साइटशी जोडलेला सशुल्क परवाना नंतर आपोआप पुनर्संचयित करता येत नाही; तो परत मिळवण्यासाठी तुम्हाला %s वर Babilim सहाय्य शी संपर्क साधावा लागेल.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'प्लगइन हटवल्यावर या साइटची ओळख पुसून टाकण्यासाठी Babilim सेट केले आहे. या साइटशी जोडलेला सशुल्क परवाना नंतर आपोआप पुनर्संचयित करता येणार नाही; तुम्हाला %s वर Babilim सहाय्य शी संपर्क साधावा लागेल. ओळख जतन ठेवण्यासाठी, रद्द करा दाबा, Babilim सेटिंग्ज मधील "अनइंस्टॉल करताना सर्व Babilim डेटा हटवा" अनटिक करा आणि पुन्हा निष्क्रिय करा. तरीही निष्क्रिय करायचे?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'या नेटवर्कवरील %1$d साइट प्लगइन हटवल्यावर तिची Babilim ओळख पुसून टाकण्यासाठी सेट केली आहे. त्या साइटशी जोडलेला सशुल्क परवाना नंतर आपोआप पुनर्संचयित करता येणार नाही; तुम्हाला %2$s वर Babilim सहाय्य शी संपर्क साधावा लागेल. ओळख जतन ठेवण्यासाठी, रद्द करा दाबा, त्या साइटच्या Babilim सेटिंग्ज मधील "अनइंस्टॉल करताना सर्व Babilim डेटा हटवा" अनटिक करा आणि पुन्हा निष्क्रिय करा. तरीही निष्क्रिय करायचे?' . "\0" . 'या नेटवर्कवरील %1$d साइट्स प्लगइन हटवल्यावर त्यांची Babilim ओळख पुसून टाकण्यासाठी सेट केल्या आहेत. त्या साइट्सशी जोडलेले सशुल्क परवाने नंतर आपोआप पुनर्संचयित करता येणार नाहीत; तुम्हाला %2$s वर Babilim सहाय्य शी संपर्क साधावा लागेल. ओळख जतन ठेवण्यासाठी, रद्द करा दाबा, प्रत्येक साइटच्या Babilim सेटिंग्ज मधील "अनइंस्टॉल करताना सर्व Babilim डेटा हटवा" अनटिक करा आणि पुन्हा निष्क्रिय करा. तरीही निष्क्रिय करायचे?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'या नेटवर्कवर एक-एक करून तपासण्यासाठी खूप जास्त साइट्स आहेत, आणि त्यापैकी काही प्लगइन हटवल्यावर त्यांची Babilim ओळख पुसून टाकण्यासाठी सेट केलेल्या असू शकतात. अशा साइटशी जोडलेला सशुल्क परवाना नंतर आपोआप पुनर्संचयित करता येणार नाही; तुम्हाला %s वर Babilim सहाय्य शी संपर्क साधावा लागेल. ओळख जतन ठेवण्यासाठी, रद्द करा दाबा, प्रत्येक साइटच्या Babilim सेटिंग्ज मधील "अनइंस्टॉल करताना सर्व Babilim डेटा हटवा" अनटिक करा आणि पुन्हा निष्क्रिय करा. तरीही निष्क्रिय करायचे?','Open Babilim settings'=>'Babilim सेटिंग्ज उघडा','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ही साइट सत्यापित करू शकले नाही, म्हणून काहीही डाउनलोड किंवा इन्स्टॉल केले जात नाही.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'सेवा तुमच्या साइटपर्यंत पोहोचू शकली नाही. फायरवॉल, सुरक्षा प्लगइन किंवा होस्टचा नियम कदाचित विनंती अवरोधित करत आहे; कृपया /wp-json/babilim/v1/challenge ला विनंत्यांना परवानगी द्या.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'तुमच्या साइटने उत्तर देण्यास खूप वेळ लावला. कृपया नंतर पुन्हा प्रयत्न करा, आणि तुमचा होस्ट खूप संथ किंवा ओव्हरलोड नाही ना ते तपासा.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'तुमच्या साइटने प्रतिसाद दिला, परंतु अपेक्षित प्रतिसाद दिला नाही. REST API दुसऱ्या प्लगइनद्वारे पुन्हा लिहिले गेले असू शकते किंवा तो एंडपॉइंट कॅश केलेला असू शकतो; कृपया /wp-json/babilim/v1/challenge ला कॅशिंग आणि रीरायटिंगमधून वगळा.','Please check that your site can be reached from the internet, then try again.'=>'कृपया तुमची साइट इंटरनेटवरून पोहोचता येण्याजोगी आहे का ते तपासा, मग पुन्हा प्रयत्न करा.','Re-verify'=>'पुन्हा सत्यापित करा','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'ही साइट सेवा एका सिंकमध्ये स्वीकारते त्या आकारापेक्षा मोठी आहे, त्यामुळे काही आयटम वगळले गेले: %1$d घटक आणि %2$d लोकेल.','This site is verified.'=>'ही साइट सत्यापित आहे.','Registration restarted.'=>'नोंदणी पुन्हा सुरू केली.','Sync complete.'=>'सिंक पूर्ण झाले.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ही साइट सक्षम करत आहे आणि तपासत आहे… हे पृष्ठ रीलोड करा किंवा नियोजित तपासणी पूर्ण होईपर्यंत थांबा.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim सक्षम करणे पूर्ण करू शकले नाही (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'एका वेळी फक्त एकच PHP विनंती हाताळणारा होस्ट ही पायरी पूर्ण करू शकत नाही.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim सक्षम आहे: ही साइट सत्यापित आहे आणि %d घटक आढळला.' . "\0" . 'Babilim सक्षम आहे: ही साइट सत्यापित आहे आणि %d घटक आढळले.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim अक्षम आहे. आणखी काहीही पाठवले जात नाही; आधीच इन्स्टॉल केलेली भाषांतरे काम करत राहतात.','Supplementary translation index rebuilt.'=>'पूरक भाषांतर अनुक्रमणिका पुन्हा तयार केली.','Sweep complete: %d file deleted.'=>'स्वच्छता पूर्ण: %d फाइल हटवली.' . "\0" . 'स्वच्छता पूर्ण: %d फाइल्स हटवल्या.','Removed %d installed component.'=>'%d इंस्टॉल केलेला घटक काढला.' . "\0" . '%d इंस्टॉल केलेले घटक काढले.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'स्वयंचलित इंस्टॉल आता बंद आहेत; हवे असल्यास सेटिंग्जमध्ये ते पुन्हा चालू करा.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim या साइटवरील ज्या प्लगइन्स आणि थीम्सना तुमच्या भाषेत भाषांतर नाही ते शोधते आणि प्रत्येकासाठी एक इन्स्टॉल करते.','Languages found on this site: %s.'=>'या साइटवर आढळलेल्या भाषा: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'उपलब्ध भाषांतरे एका क्लिकने इन्स्टॉल करता येतात, आणि नसलेली भाषांतरे मागवता येतात. त्यानंतर नवीन भाषांतरे आणि अपडेट्स आपोआप इन्स्टॉल होतात (मोफत योजनेत, फक्त आधीपासून मोफत स्लॉट वापरणाऱ्या प्लगइन्स आणि थीम्ससाठी).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'मोफत योजना मर्यादित संख्येच्या प्लगइन्स आणि थीम्सना लागू होते; तुम्ही Babilim सक्षम केल्यानंतर तुमचा नेमका कोटा सेटिंग्जमध्ये दिसेल.','What is sent when you enable Babilim'=>'तुम्ही Babilim सक्षम करता तेव्हा काय पाठवले जाते','Enabling…'=>'सक्षम करत आहे…','Enable Babilim'=>'Babilim सक्षम करा','By clicking Enable, you agree to send the information listed above to Babilim.'=>'सक्षम करा वर क्लिक करून, तुम्ही वर नमूद केलेली माहिती Babilim ला पाठवण्यास सहमती देता.','Check again now'=>'आता पुन्हा तपासा','Babilim installed %d translation automatically since your last visit.'=>'तुमच्या मागील भेटीनंतर Babilim ने %d भाषांतर आपोआप इन्स्टॉल केले.' . "\0" . 'तुमच्या मागील भेटीनंतर Babilim ने %d भाषांतरे आपोआप इन्स्टॉल केली.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ही साइट सक्षम करत आहे आणि तपासत आहे… (शेवटचा प्रयत्न: %s)','Check again'=>'पुन्हा तपासा','No components synced yet.'=>'अद्याप कोणतेही घटक सिंक झालेले नाहीत.','%d succeeded'=>'%d यशस्वी' . "\0" . '%d यशस्वी','%d skipped'=>'%d वगळले' . "\0" . '%d वगळले','%d failed'=>'%d अयशस्वी' . "\0" . '%d अयशस्वी','%d not yet tried'=>'%d बाबतीत अद्याप प्रयत्न केलेले नाहीत' . "\0" . '%d बाबतीत अद्याप प्रयत्न केलेले नाहीत','%1$s nothing to do.'=>'%1$s करण्यासारखे काही नाही.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'सामूहिक डाउनलोड:','Bulk update:'=>'सामूहिक अद्यतन:','Bulk request:'=>'सामूहिक विनंती:','per day'=>'प्रति दिवस','Wrong meaning'=>'चुकीचा अर्थ','Wrong term'=>'चुकीचा शब्द','Broken placeholder'=>'बिघडलेला प्लेसहोल्डर','Wrong for this context'=>'या संदर्भासाठी चुकीचे','Wrong plural form'=>'चुकीचे अनेकवचन रूप','Negation reversed'=>'नकार उलटा झाला आहे','Translation does not load'=>'भाषांतर लोड होत नाही','problem report categoryOther'=>'इतर','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'पुढे चालू आहे…','Continue next batch (%d left)'=>'पुढील बॅच सुरू ठेवा (%d शिल्लक)','Search components'=>'घटक शोधा','These are the languages this site uses. You can change them in %s.'=>'या या साइटवर वापरल्या जाणाऱ्या भाषा आहेत. तुम्ही त्या %s मध्ये बदलू शकता.','Upload this component?'=>'हा घटक अपलोड करायचा?','There is no upload waiting for confirmation.'=>'पुष्टीची वाट पाहत असलेले कोणतेही अपलोड नाही.','Back'=>'मागे','To translate this component, Babilim needs its source.'=>'हा घटक भाषांतरित करण्यासाठी Babilim ला त्याचा स्रोत आवश्यक आहे.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (आवृत्ती %2$s) ची संपूर्ण प्लगइन किंवा थीम डिरेक्टरी Babilim वर अपलोड केली जाईल.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'त्या डिरेक्टरीमध्ये की, लॉग किंवा ग्राहकांचा डेटा असल्यास तोही अपलोड केला जाईल. सेवा सामान्य संवेदनशील फायली (कॉन्फिगरेशन, एन्व्हायर्नमेंट, डेटाबेस डंप, लॉग, की) काढून टाकते, पण सर्व काही सापडेलच याची हमी देऊ शकत नाही.','The upload is kept until you ask Babilim to delete it.'=>'तुम्ही Babilim ला ते हटवण्यास सांगेपर्यंत अपलोड ठेवले जाते.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'ते सेवेच्या होस्टिंग प्रदात्याकडे साठवले जाते आणि अनुवाद तयार करण्यासाठी AI मॉडेल्सद्वारे प्रक्रिया केली जाते.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'मूळ मजकूर आणि त्यापासून तयार केलेले अनुवाद, हीच आवृत्ती इन्स्टॉल करणाऱ्या इतर साइट्सना पुरवले जातील.','By continuing you confirm that you have the right to upload this component.'=>'पुढे गेल्यास, हा घटक अपलोड करण्याचा अधिकार तुमच्याकडे आहे याची तुम्ही पुष्टी करता.','Upload and request'=>'अपलोड करा आणि विनंती करा','Uploading…'=>'अपलोड होत आहे…','Cancel'=>'रद्द करा','Uploading'=>'अपलोड होत आहे','There is no upload in progress.'=>'कोणतेही अपलोड प्रगतीत नाही.','Uploading part %1$d of %2$d…'=>'%2$d पैकी %1$d भाग अपलोड होत आहे…','Continue'=>'सुरू ठेवा','Confirm'=>'पुष्टी करा','Remove'=>'काढा','Roll back'=>'मागे फिरवा','Nothing to confirm.'=>'पुष्टी करण्यासारखे काही नाही.','Choose a language'=>'भाषा निवडा','Roll back and report'=>'मागे फिरवा आणि अहवाल द्या','Report a problem'=>'समस्येचा अहवाल द्या','Nothing to choose.'=>'निवडण्यासारखे काही नाही.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. भाषा निवडा.','Supplementary translations'=>'पूरक भाषांतरे','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'प्रत्येक लोकेलच्या सामायिक डीफॉल्ट-डोमेन पूरक भाषांतरात प्रत्येक घटकाचे स्वतःचे योगदान.','Component'=>'घटक','Language'=>'भाषा','Included in index'=>'अनुक्रमणिकेत समाविष्ट','Entries'=>'नोंदी','Conflicting keys'=>'विसंगत की','Yes'=>'होय','No — component inactive'=>'नाही — घटक निष्क्रिय','No — installed version differs from the active one'=>'नाही — इन्स्टॉल केलेली आवृत्ती सक्रिय आवृत्तीपेक्षा वेगळी आहे','No — component removed'=>'नाही — घटक काढला','No'=>'नाही','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'हे फक्त नेटवर्क प्रशासकच करू शकतो, कारण यामुळे या नेटवर्कवरील प्रत्येक साइटद्वारे सामायिक केलेल्या भाषांतर फाइल्स बदलतात.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ही साइट पडताळण्याचे काम पूर्ण करू शकले नाही (सेवा तिच्यापर्यंत परत पोहोचू शकली नाही). नोंदणी थांबवली आहे.','This site already has an active registration that can no longer be recovered automatically.'=>'या साइटची सक्रिय नोंदणी आधीपासून आहे, जी आता आपोआप पुनर्प्राप्त करता येत नाही.','Restart registration'=>'नोंदणी पुन्हा सुरू करा','Babilim settings'=>'Babilim सेटिंग्ज','General'=>'सामान्य','Advanced'=>'प्रगत','Languages'=>'भाषा','Automatic installs'=>'स्वयंचलित इन्स्टॉल','Install available translations automatically'=>'उपलब्ध भाषांतरे आपोआप इन्स्टॉल करा','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'मोफत योजनेवर, तुमच्या मोकळ्या जागांपैकी एक आधीच वापरणारे घटकच आपोआप इन्स्टॉल केले जातात, त्यामुळे नवीन जागा घेतली जात नाही.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'ही साइट मल्टीसाइट नेटवर्कचा भाग आहे, जी नवीन भाषांतरे आपोआप इन्स्टॉल करत नाही. आधीच इन्स्टॉल केलेली भाषांतरे मात्र अद्ययावत केली जातात.','Custom overrides'=>'सानुकूल अधिलिखिते','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'सर्व काही साफ करताना किंवा हा प्लगइन अनइन्स्टॉल करताना माझे स्वतःचे भाषांतर ओव्हरराइड्स ठेवा.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'तुम्ही %s मध्ये ठेवलेल्या भाषांतर फाइल्सना नेहमी Babilim च्या फाइल्सपेक्षा प्राधान्य मिळते. तुम्ही हे अनचेक केल्याशिवाय त्या ठेवल्या जातात.','Uninstall'=>'अनइन्स्टॉल','Delete all Babilim data on uninstall'=>'अनइंस्टॉल करताना सर्व Babilim डेटा हटवा','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'डीफॉल्टनुसार बंद: प्लगइन हटवल्यास या साइटची ओळख राखली जाते, त्यामुळे पुन्हा इन्स्टॉल केल्यावर ती पुन्हा वापरता येते.','Account'=>'खाते','Save changes'=>'बदल जतन करा','Disable Babilim'=>'Babilim अक्षम करा','Installed translations are kept, but no further checks or downloads will run.'=>'इन्स्टॉल केलेली भाषांतरे ठेवली जातात, परंतु पुढील तपासण्या किंवा डाउनलोड चालणार नाहीत.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim अक्षम करायचे? इन्स्टॉल केलेली भाषांतरे ठेवली जातील, परंतु पुढील तपासण्या किंवा डाउनलोड चालणार नाहीत.','This site is not registered with Babilim yet.'=>'ही साइट अद्याप Babilim कडे नोंदणीकृत नाही.','This site is already licensed. Reload the page.'=>'या साइटला आधीच परवाना आहे. पृष्ठ रीलोड करा.','Checkout is not available for this site right now.'=>'या साइटसाठी चेकआउट सध्या उपलब्ध नाही.','Could not start checkout: %s'=>'चेकआउट सुरू करता आले नाही: %s','Babilim is not enabled.'=>'Babilim सक्षम केलेले नाही.','Not registered yet'=>'अद्याप नोंदणी झालेली नाही','Not verified'=>'सत्यापित नाही','Verified'=>'सत्यापित','Status'=>'स्थिती','Licensed'=>'परवानाधारक','Partner'=>'भागीदार','Free'=>'मोफत','License'=>'परवाना','Upgrade this site'=>'या साइटला अपग्रेड करा','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'या साइटसाठी एकवेळची खरेदी: %1$s %2$s. भविष्यातील सर्व भाषांतर अद्यतने समाविष्ट. पेमेंट Paddle द्वारे नवीन टॅबमध्ये हाताळले जाते.','This issues a new restore code and the previous one stops working. Continue?'=>'यामुळे नवीन पुनर्संचयित कोड जारी होईल आणि आधीचा काम करणे थांबवेल. पुढे जायचे?','Show a new restore code'=>'नवीन पुनर्संचयित कोड दाखवा','rc_…'=>'rc_…','Restore code'=>'पुनर्संचयित कोड','Restore purchase'=>'खरेदी पुनर्संचयित करा','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'यापूर्वी या डोमेनसाठी परवाना खरेदी केला होता का? चेकआउटच्या वेळी मिळालेला पुनर्संचयित कोड प्रविष्ट करा.','That does not look like a restore code.'=>'हा पुनर्संचयित कोड असल्यासारखा दिसत नाही.','This restore code was not recognised for this site.'=>'हा पुनर्संचयित कोड या साइटसाठी ओळखला गेला नाही.','Too many attempts. Try again tomorrow.'=>'खूप जास्त प्रयत्न. उद्या पुन्हा प्रयत्न करा.','This site must be verified first.'=>'ही साइट आधी सत्यापित करणे आवश्यक आहे.','Could not restore the purchase: %s'=>'खरेदी पुनर्संचयित करता आली नाही: %s','Purchase restored. This site is now licensed.'=>'खरेदी पुनर्संचयित झाली. ही साइट आता परवानाधारक आहे.','This site has no purchase to show a code for.'=>'या साइटसाठी कोड दाखवण्यासाठी कोणतीही खरेदी नाही.','Could not show a new restore code: %s'=>'नवीन पुनर्संचयित कोड दाखवता आला नाही: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'तुमचा नवीन पुनर्संचयित कोड: %s. तो सुरक्षित ठिकाणी ठेवा — मागील कोड आता कार्य करत नाही.','What is sent when Babilim checks this site'=>'Babilim ही साइट तपासते तेव्हा काय पाठवले जाते','(detected)'=>'(आढळले)','No language is managed yet.'=>'अद्याप कोणतीही भाषा व्यवस्थापित केलेली नाही.','Babilim adds translations for every language checked here.'=>'येथे निवडलेल्या प्रत्येक भाषेसाठी Babilim भाषांतरे जोडते.','Add another language'=>'आणखी भाषा जोडा','Choose a language…'=>'भाषा निवडा…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'सेवेकडून संपूर्ण WordPress.org लोकेल यादी लोड करता आली नाही, त्यामुळे सध्या इतर कोणतीही भाषा जोडता येणार नाही.','Theme'=>'थीम','Plugin'=>'प्लगइन','Free quota'=>'मोफत कोटा','Downloads: %1$d/%2$d (%3$s)'=>'डाउनलोड: %1$d/%2$d (%3$s)','Supplementary translation index'=>'पूरक भाषांतर अनुक्रमणिका','Built'=>'तयार केले','Included'=>'समाविष्ट','Excluded'=>'वगळलेले','Already in WordPress core'=>'WordPress कोअरमध्ये आधीपासून आहे','Supplementary translation maintenance'=>'पूरक भाषांतर देखभाल','Maintenance status is not available right now.'=>'देखभालीची स्थिती सध्या उपलब्ध नाही.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s रोजी स्वच्छता थांबवण्यात आली: %2$s. काहीही हटवले गेले नाही.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'शेवटची स्वच्छता %1$s रोजी: %2$d नव्याने चिन्हांकित, %3$d फाइल हटवल्या, %4$d नोंदी काढल्या.','No cleanup has run yet.'=>'अद्याप कोणतीही स्वच्छता चालवली गेली नाही.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s रोजी भाषांतर अनुक्रमणिकेचे लेखन (%2$s) दुसऱ्या विनंतीशी विसंगत ठरले आणि लागू केले गेले नाही; सर्वात अलीकडील आवृत्ती ठेवली गेली.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s रोजी भाषांतर अनुक्रमणिकेचे लेखन (%2$s) पूर्ण होऊ शकले नाही आणि लागू केले गेले नाही (%3$s).','Maintenance'=>'देखभाल','Rebuild index now'=>'इंडेक्स आता पुन्हा तयार करा','Sweep now'=>'आता स्वच्छ करा','Danger zone'=>'धोकादायक विभाग','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'या साइटवरील प्रत्येक प्लगइन आणि थीमसाठी Babilim ने स्थापित केलेली प्रत्येक भाषा फाइल काढून टाकते.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim ने स्थापित केलेले सर्व काही काढून टाकायचे? यामुळे या साइटवरील प्रत्येक प्लगइन आणि थीमसाठी Babilim ने स्थापित केलेल्या सर्व भाषा फाइल्स हटवल्या जातील.','Remove everything Babilim installed'=>'Babilim ने स्थापित केलेले सर्व काही काढून टाका','This string is too long to be sent as a report, so no report form is offered for it.'=>'हा स्ट्रिंग अहवाल म्हणून पाठवण्यासाठी खूप मोठा आहे, म्हणून त्यासाठी अहवाल फॉर्म दिलेला नाही.','Category'=>'श्रेणी','Choose a category…'=>'श्रेणी निवडा…','Roll back and send report'=>'रोलबॅक करा आणि अहवाल पाठवा','Send report'=>'अहवाल पाठवा','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'या घटकातील काही मजकूर त्याच्या लेखकाने हार्ड-कोड केलेला आहे आणि भाषा पॅकद्वारे त्याचे भाषांतर करता येत नाही.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'थीमसह समाविष्ट','Bundled with the plugin'=>'प्लगइनसह समाविष्ट','Upload was not accepted'=>'अपलोड स्वीकारले गेले नाही','Upload expired before it finished'=>'अपलोड पूर्ण होण्यापूर्वीच कालबाह्य झाले','No translation'=>'भाषांतर नाही','Upload in progress — continue or cancel'=>'अपलोड सुरू आहे — सुरू ठेवा किंवा रद्द करा','Scheduled, waiting to be processed'=>'नियोजित, प्रक्रियेची प्रतीक्षा','Translating…'=>'भाषांतर सुरू आहे…','Translation failed'=>'भाषांतर अयशस्वी','Free quota used'=>'मोफत कोटा वापरला','Needs a paid license'=>'सशुल्क परवाना आवश्यक','Not supported'=>'समर्थित नाही','Status unknown'=>'स्थिती अज्ञात','translation statusInstalled'=>'स्थापित','Update available'=>'अद्यतन उपलब्ध','Removed after a failed integrity check'=>'अखंडता तपासणी अयशस्वी झाल्यानंतर काढले','Installed · built for %s, new version scheduled'=>'स्थापित · %s साठी तयार केले, नवीन आवृत्ती नियोजित','Installed · built for a different version, new version scheduled'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केले, नवीन आवृत्ती नियोजित','Installed · built for %s, translating the new version…'=>'स्थापित · %s साठी तयार केले, नवीन आवृत्तीचे भाषांतर सुरू आहे…','Installed · built for a different version, translating the new version…'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केले, नवीन आवृत्तीचे भाषांतर सुरू आहे…','Installed · built for %1$s, this site has %2$s'=>'स्थापित · %1$s साठी तयार केले, या साइटवर %2$s आहे','Installed · built for %s'=>'स्थापित · %s साठी तयार केले','Installed · built for a different version'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केले','Installed · built for %s, new version failed'=>'स्थापित · %s साठी तयार केलेले, नवीन आवृत्ती अयशस्वी','Installed · built for a different version, new version failed'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केलेले, नवीन आवृत्ती अयशस्वी','Installed · built for %s, new version needs a paid license'=>'स्थापित · %s साठी तयार केलेले, नवीन आवृत्तीसाठी सशुल्क परवाना आवश्यक','Installed · built for a different version, new version needs a paid license'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केलेले, नवीन आवृत्तीसाठी सशुल्क परवाना आवश्यक','Installed · built for %s, free quota used'=>'स्थापित · %s साठी तयार केलेले, मोफत कोटा वापरला','Installed · built for a different version, free quota used'=>'स्थापित · वेगळ्या आवृत्तीसाठी तयार केलेले, मोफत कोटा वापरला','translation statusAvailable'=>'उपलब्ध','Installed · %s'=>'स्थापित · %s','Available · %s'=>'उपलब्ध · %s','Update'=>'अद्यतनित करा','Download'=>'डाउनलोड करा','Updating…'=>'अद्यतनित होत आहे…','Downloading…'=>'डाउनलोड होत आहे…','Retry request'=>'विनंती पुन्हा करा','Request newer translation'=>'नवीन भाषांतराची विनंती करा','Request translation'=>'भाषांतराची विनंती करा','Requesting…'=>'विनंती करत आहे…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'भाषांतराची विनंती केल्यास तुमची एक मोकळी जागा वापरली जाते, जोपर्यंत हा घटक आधीच एक वापरत नसेल. अयशस्वी भाषांतर ती जागा परत देत नाही.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'हा घटक अद्याप तुमची कोणतीही मोकळी जागा वापरत नसेल, तर भाषांतराची विनंती केल्यास एक वापरली जाते. अयशस्वी भाषांतर ती जागा परत देत नाही. सुरू ठेवायचे?','No plugins or themes found.'=>'कोणतेही प्लगइन किंवा थीम आढळले नाहीत.','Clear filters'=>'फिल्टर साफ करा','No components match these filters. %s'=>'या फिल्टरशी जुळणारा कोणताही घटक नाही. %s','Select all'=>'सर्व निवडा','All'=>'सर्व','Available'=>'उपलब्ध','Updates'=>'अद्यतने','Requestable'=>'विनंती करण्यायोग्य','Installed'=>'स्थापित','Plugins'=>'प्लगइन','Themes'=>'थीम','All languages'=>'सर्व भाषा','%d to install'=>'स्थापित करण्यासाठी %d' . "\0" . 'स्थापित करण्यासाठी %d','Language:'=>'भाषा:','Bulk actions apply to every matching language of each selected component.'=>'गटशः क्रिया प्रत्येक निवडलेल्या घटकाच्या सर्व जुळणाऱ्या भाषांना लागू होतात.','Bulk actions apply only to the selected language of each selected component.'=>'गटशः क्रिया प्रत्येक निवडलेल्या घटकाच्या केवळ निवडलेल्या भाषा ला लागू होतात.','Version %s'=>'आवृत्ती %s','Theme · %s'=>'थीम · %s','Plugin · %s'=>'प्लगइन · %s','Remove the %2$s translation of %1$s from this site?'=>'%1$s चे %2$s भाषेतील भाषांतर या साइटवरून काढून टाकायचे?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s चे %2$s भाषांतर मागील बिल्डवर रोल बॅक करायचे?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'नोंदणी आव्हान अपेक्षित स्वरूपात नाही.','That is not a valid build identifier.'=>'हा वैध बिल्ड अभिज्ञापक नाही.','Refusing to write outside the Babilim language-file directory.'=>'Babilim भाषा-फाइल निर्देशिकेच्या बाहेर लिहिण्यास नकार दिला.','Could not write the downloaded package to disk.'=>'डाउनलोड केलेले पॅकेज डिस्कवर लिहिता आले नाही.','Unexpected HTTP %d response.'=>'अनपेक्षित HTTP %d प्रतिसाद.','This site\'s URL, so the service can verify you own it.'=>'या साइटचा URL, जेणेकरून सेवा तुम्ही त्याचे मालक असल्याची पडताळणी करू शकेल.','Your WordPress version, to serve compatible translation files.'=>'तुमची WordPress आवृत्ती, सुसंगत भाषांतर फाइल्स पुरवण्यासाठी.','Your PHP version, for compatibility.'=>'तुमची PHP आवृत्ती, सुसंगततेसाठी.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'या प्लगइनची स्वतःची आवृत्ती, जेणेकरून ती संवाद साधण्यासाठी खूप जुनी असल्यास सेवा तुम्हाला ती अपडेट करण्यास सांगू शकेल.','This site\'s configured locale.'=>'या साइटचे कॉन्फिगर केलेले लोकेल.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'या साइटवर वापरात असलेले प्रत्येक लोकेल (साइट लोकेल, स्थापित भाषा पॅक, वापरकर्ता लोकेल आणि तुम्ही स्वतः जोडलेले कोणतेही). कोणत्याही लोकेलला इतरांपेक्षा वेगळी वागणूक दिली जात नाही.','(a public key generated for this site)'=>'(या साइटसाठी तयार केलेली सार्वजनिक की)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'या साइटची इंस्टॉल सार्वजनिक की, विनंत्या खरोखर या साइटवरून येतात हे सिद्ध करण्यासाठी वापरली जाते. फक्त सार्वजनिक भाग कधीही पाठवला जातो.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'प्रत्येक स्थापित प्लगइन/थीम: तिचा स्लग, आवृत्ती, मजकूर डोमेन, ती wp.org वरील सूची आहे का, तिची स्वतःची समाविष्ट लोकेल, आणि तुम्ही कोणत्या लोकेलसाठी Babilim भाषांतर आधीच स्थापित केले आहे.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'केवळ जेव्हा तुम्ही WordPress.org वर नसलेल्या प्लगइन किंवा थीमसाठी अपलोडची पुष्टी करता: त्या घटकाची संपूर्ण निर्देशिका, zip स्वरूपात.','(generic codes and coordinates only)'=>'(फक्त सामान्य कोड आणि निर्देशांक)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'प्रलंबित निदान घटनांपैकी जास्तीत जास्त 20 (उदा. अखंडता तपासणीत अयशस्वी झालेली फाइल), प्रत्येक केवळ कोड, घटक आणि लोकेल असलेली, आणि कधीही कोणतीही स्ट्रिंग सामग्री किंवा भाषांतरित मजकूर नसलेली.','Unsafe locale: %s'=>'असुरक्षित लोकेल: %s','Manifest unavailable: %s'=>'मॅनिफेस्ट उपलब्ध नाही: %s','Could not determine active components; the existing merged index was left unchanged.'=>'सक्रिय घटक निश्चित करता आले नाहीत; विद्यमान मर्ज केलेला इंडेक्स बदलला नाही.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'इंस्टॉल केलेले प्लगइन/थीम निश्चित करता आल्या नाहीत; स्वीप वगळला, काहीही हटवले नाही.','Sweep aborted without orphaning anything: %s.'=>'स्वच्छता कोणतीही नोंद अनाथ न करता थांबवली गेली: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'स्वच्छता पूर्ण झाली, परंतु तिचे काही बदल भाषांतर अनुक्रमणिकेत नोंदवता आले नाहीत; पुढील स्वच्छता ते पुन्हा प्रयत्न करेल.','component kind in the sweep brake messagetheme'=>'थीम','component kind in the sweep brake messageplugin'=>'प्लगइन','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ते प्रत्येक व्यवस्थापित %1$s घटक अनाथ करेल (%2$d पैकी %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'ते एकूण %2$d व्यवस्थापित घटकांपैकी %1$d अनाथ करेल (निम्म्यापेक्षा जास्त)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' साठीची एकत्रित अनुक्रमणिका पुन्हा तयार केली गेली, परंतु भाषांतर अनुक्रमणिकेत ती नोंदवता आली नाही; पुढील पुनर्रचना पुन्हा प्रयत्न करेल.','Could not write the staged merged index.'=>'टप्प्याटप्प्याने तयार केलेली एकत्रित अनुक्रमणिका लिहिता आली नाही.','Re-parsed entry count did not match the built index.'=>'पुन्हा पार्स केलेल्या नोंदींची संख्या तयार केलेल्या इंडेक्सशी जुळली नाही.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' साठीची एकत्रित अनुक्रमणिका जागेवर हलवता आली नाही; आधीची वापरात असलेली अनुक्रमणिका (असल्यास) अर्धवट अद्यतनित राहू नये म्हणून काढून टाकली गेली. पुढील यशस्वी पुनर्रचनेपर्यंत या लोकेलसाठी कोणतेही डीफॉल्ट-डोमेन पूरक भाषांतर दिले जाणार नाही.','Could not open zip: %s'=>'zip उघडता आली नाही: %s','Zip has no manifest.json.'=>'झिपमध्ये manifest.json नाही.','manifest.json in the zip is not valid JSON.'=>'झिपमधील manifest.json हा वैध JSON नाही.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json मधील \'%s\' अपेक्षित मूल्याशी जुळत नाही.','Another installation is running; try again in a moment.'=>'दुसरे इंस्टॉलेशन चालू आहे; थोड्या वेळाने पुन्हा प्रयत्न करा.','Not a valid server_build_id: %s'=>'वैध server_build_id नाही: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'पॅकेज मॅनिफेस्टचा kind \'%1$s\' विनंती केलेल्या kind \'%2$s\' शी जुळत नाही.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'पॅकेजचे मजकूर डोमेन \'%1$s\' या साइटवरील घटकाच्या प्रतीशी (\'%2$s\') जुळत नाही, म्हणून ते स्थापित केले गेले नाही.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'दिलेले डोमेन \'%1$s\' पॅकेज मॅनिफेस्टच्या स्वतःच्या स्लगशी \'%2$s\' किंवा त्याच्या text_domain शी \'%3$s\' जुळत नाही.','Unsafe slug: %s'=>'असुरक्षित स्लग: %s','Unsafe text_domain: %s'=>'असुरक्षित text_domain: %s','The package has no %s for its own text domain.'=>'पॅकेजमध्ये त्याच्या स्वतःच्या मजकूर डोमेनसाठी %s नाही.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json मध्ये \'%s\' नाही किंवा अवैध आहे.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json मध्ये \'entries\' नाही किंवा अवैध आहे.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json मध्ये \'files\' नाही किंवा अवैध आहे.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json मध्ये \'extra_domains\' नाही किंवा अवैध आहे.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json मध्ये \'build_no\' नाही किंवा अवैध आहे.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json मधील \'server_build_id\' वैध बिल्ड आयडी नाही.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json मधील \'contract\' वैध आवृत्ती स्ट्रिंग नाही.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json मधील \'status\' (स्थिती) \'published\' (प्रकाशित) असणे आवश्यक आहे.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json मधील \'kind\' हे \'plugin\' किंवा \'theme\' (थीम) असणे आवश्यक आहे.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json मध्ये अवैध \'default_domain_entries\' आहे.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json मध्ये अवैध \'default_domain_files\' आहे.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest मध्ये \'%s\' नाही किंवा अवैध आहे.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest मधील \'server_build_id\' वैध बिल्ड आयडी नाही.','No record for %s'=>'%s साठी कोणतीही नोंद नाही','One or more served files no longer match the manifest.'=>'वापरात असलेल्या एक किंवा अधिक फायली आता मॅनिफेस्टशी जुळत नाहीत.','No previous build to roll back to.'=>'परत जाण्यासाठी मागील बिल्ड नाही.','The change could not be recorded in the translation index; please try again.'=>'हा बदल भाषांतर अनुक्रमणिकेत नोंदवता आला नाही; कृपया पुन्हा प्रयत्न करा.','Unknown kind: %s'=>'अज्ञात प्रकार: %s','Unsafe domain: %s'=>'असुरक्षित डोमेन: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'मजकूर डोमेन \'%1$s\' (%2$s) दुसऱ्या स्थापित घटकासाठी (%3$s) आधीच वापरात आहे; काहीही स्थापित केले गेले नाही.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'मागील आवृत्तीवर परत गेल्यास \'%1$s\' (%2$s) अधिलिखित होईल, जे आता दुसऱ्या स्थापित घटकासाठी (%3$s) वापरात आहे; काहीही बदलले गेले नाही.','Zip is missing expected file: %s'=>'Zip मध्ये अपेक्षित फाइल नाही: %s','sha256 mismatch for %s'=>'%s साठी sha256 जुळत नाही','The package declares no main translation file.'=>'पॅकेजमध्ये मुख्य भाषांतर फाइल घोषित केलेली नाही.','Zip is missing expected default file: %s'=>'Zip मध्ये अपेक्षित default फाइल नाही: %s','sha256 mismatch for default/%s'=>'default/%s साठी sha256 जुळत नाही','Could not stage %s'=>'%s स्टेज करता आले नाही','Could not stage default/%s'=>'default/%s स्टेज करता आले नाही','Entry count mismatch for %s'=>'%s साठी नोंदींची संख्या जुळत नाही','Could not verify entry count for %s'=>'%s साठी नोंदींची संख्या पडताळता आली नाही','l10n.php entry count mismatch for %s'=>'%s साठी l10n.php नोंदींची संख्या जुळत नाही','Default supplement entry count mismatch.'=>'Default पूरक नोंदींची संख्या जुळत नाही.','The package produced no servable main translation file.'=>'पॅकेजने वापरण्यायोग्य मुख्य भाषांतर फाइल तयार केली नाही.','Could not prepare %s for rollback.'=>'%s मागील आवृत्तीवर परत जाण्यासाठी तयार करता आली नाही.','Could not back up %s before replacing it.'=>'%s बदलण्यापूर्वी त्याचा बॅकअप घेता आला नाही.','Could not move %s into place.'=>'%s जागी हलवता आले नाही.','Could not read %s back after moving it into place.'=>'%s जागेवर हलवल्यानंतर परत वाचता आली नाही.','English (United States)'=>'इंग्रजी (युनायटेड स्टेट्स)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest उपलब्ध नाही: %s','could not read _manifest.json: %s'=>'_manifest.json वाचता आली नाही: %s','failed to parse _manifest.json: %s'=>'_manifest.json पार्स करण्यात अयशस्वी: %s','_manifest.json has an unexpected structure'=>'_manifest.json ची रचना अनपेक्षित आहे','Could not create the package archive.'=>'पॅकेज आर्काइव्ह तयार करता आले नाही.','No writable temporary directory is available for packaging.'=>'पॅकेजिंगसाठी लिहिता येण्याजोगी कोणतीही तात्पुरती डिरेक्टरी उपलब्ध नाही.','A file in the component could not be read, so it was not packaged.'=>'घटकातील एक फाइल वाचता आली नाही, म्हणून ती पॅकेज केली गेली नाही.','Only plugins and themes can be packaged.'=>'फक्त प्लगइन आणि थीम पॅकेज करता येतात.','The component\'s main file was not found.'=>'घटकाची मुख्य फाइल सापडली नाही.','The component is not inside the plugins or themes directory.'=>'घटक प्लगइन किंवा थीम डिरेक्टरीमध्ये नाही.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim ची या टप्प्यासाठीची वेळ संपली आणि ते पुढील तपासणीत सुरू राहील.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ही साइट सत्यापित करू शकले नाही, त्यामुळे सत्यापन यशस्वी होईपर्यंत काहीही डाउनलोड किंवा इंस्टॉल केले जाणार नाही.','Registration response was missing required fields.'=>'नोंदणी प्रतिसादात आवश्यक फील्ड गहाळ होती.','No pending challenge to verify.'=>'सत्यापित करण्यासाठी कोणतेही प्रलंबित आव्हान नाही.','Verify response was missing site_token.'=>'सत्यापन प्रतिसादात site_token गहाळ होता.','No site id is on file to rotate a token for.'=>'टोकन बदलण्यासाठी कोणताही साइट आयडी नोंदवलेला नाही.','Rotate-token response was missing site_token.'=>'टोकन-बदल प्रतिसादात site_token गहाळ होता.','nonce must be a hexadecimal string.'=>'नॉन्स ही हेक्साडेसिमल स्ट्रिंग असणे आवश्यक आहे.','No pending challenge for this nonce.'=>'या नॉन्ससाठी कोणतेही प्रलंबित आव्हान नाही.','Too many requests.'=>'खूप जास्त विनंत्या.','The service asked this site to wait before syncing again.'=>'सेवेने या साइटला पुन्हा सिंक करण्यापूर्वी थांबण्यास सांगितले.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'या साइटवर %2$d भाषांमध्ये %1$d घटक आहेत, ज्यासाठी %3$d तपासणी बॅचेस आवश्यक आहेत; Babilim प्रत्येक रनमध्ये जास्तीत जास्त %4$d हाताळू शकते. सेटिंग्जमध्ये व्यवस्थापित भाषा कमी करा किंवा न वापरलेले प्लगइन आणि थीम निष्क्रिय करा, नंतर आता पुन्हा तपासा दाबा.','Babilim could not finish checking this site.'=>'Babilim ही साइट तपासणे पूर्ण करू शकले नाही.','This site\'s address is too long for Babilim to register.'=>'या साइटचा पत्ता Babilim ला नोंदवण्यासाठी खूप मोठा आहे.','This site\'s locale code is not one Babilim can register.'=>'या साइटचा लोकेल कोड Babilim नोंदणी करू शकेल असा नाही.','The download response was missing a usable location.'=>'डाउनलोड प्रतिसादात वापरण्यायोग्य स्थान नव्हते.','The service\'s upload offer was incomplete.'=>'सेवेची अपलोड ऑफर अपूर्ण होती.','This component is larger than the service accepts, so it cannot be uploaded.'=>'हा घटक सेवा स्वीकारते त्यापेक्षा मोठा आहे, त्यामुळे तो अपलोड करता येत नाही.','The packaged component could not be read.'=>'पॅकेज केलेला घटक वाचता आला नाही.','A part of the upload kept failing, so the upload was cancelled.'=>'अपलोडचा एक भाग वारंवार अयशस्वी होत राहिला, म्हणून अपलोड रद्द केले गेले.','Could not read: %s'=>'वाचता आले नाही: %s']];